package com.boutique.order.controller;import com.boutique.order.dto.*;import com.boutique.order.service.OrderService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/orders") public class OrderController {private final OrderService service;public OrderController(OrderService s){service=s;} @PostMapping public ResponseEntity<OrderResponse> create(@Valid @RequestBody CreateOrderRequest r){var x=service.create(r);return ResponseEntity.status(HttpStatus.CREATED).body(x);} @GetMapping("/{id}") public OrderResponse get(@PathVariable UUID id){return service.get(id);} @PostMapping("/{id}/confirm") public OrderResponse confirm(@PathVariable UUID id,@RequestParam UUID paymentId){return service.confirm(id,paymentId);} @PostMapping("/{id}/payment-failed") @ResponseStatus(HttpStatus.NO_CONTENT) public void failed(@PathVariable UUID id){service.paymentFailed(id);}}
